/// <summary>
/// The <c>ConDemoPackProcessGuideRegisterStep</c> class registers the packed container without
/// showing a screen to the worker.
/// </summary>
[ProcessGuideStepName(classStr(ConDemoPackProcessGuideRegisterStep))]
public class ConDemoPackProcessGuideRegisterStep extends ProcessGuideStepWithoutPrompt
{
}

Method.Source:
/// <summary>
/// Registers the container the worker scanned on the previous screen.
/// </summary>
protected void doExecute()
{
    WhsrfPassthrough pass = controller.parmSessionState().parmPass();

    WHSContainerId containerId = pass.lookupStr(ProcessGuideDataTypeNames::ContainerId);
    WHSContainerTable containerTable = WHSContainerTable::findByContainerId(containerId);

    WHSContainerTable::closeContainer(
        containerTable.ShipmentId,
        containerId,
        pass.lookupNum(ProcessGuideDataTypeNames::Weight),
        pass.lookupStr(ProcessGuideDataTypeNames::WHSWeightUOM),
        pass.lookupStr(ProcessGuideDataTypeNames::PutLocationId),
        false);

    this.addProcessCompletionMessage();

    super();
}
